function nameFor(displayName: string, modelID: string): string {
  const clean = displayName || modelID
  // strip org prefix like "deepseek/deepseek-v4-flash" → "DeepSeek V4 Flash"
  const last = clean.split("/").pop() ?? clean
  const spaced = last.replace(/[-_]/g, " ")
  return spaced
    .split(" ")
    .filter((token) => token.length > 0)
    .map((token) => BRAND_TOKENS[token.toLowerCase()] ?? (token === token.toLowerCase() ? token[0]!.toUpperCase() + token.slice(1) : token))
    .join(" ")
    .trim()
}
// ---------------------------------------------------------------------------
// Color helpers (RGBA from hex; gradient interpolation)
// ---------------------------------------------------------------------------

type RGBA = { r: number; g: number; b: number; a: number }

function hexToRgba(hex: string): RGBA | undefined {
  const value = hex.replace("#", "").trim()
  if (value.length !== 6 && value.length !== 8) return undefined
  const num = Number.parseInt(value, 16)
  if (Number.isNaN(num)) return undefined
  if (value.length === 6) return { r: (num >> 16) & 255, g: (num >> 8) & 255, b: num & 255, a: 255 }
  return { r: (num >>> 24) & 255, g: (num >>> 16) & 255, b: (num >>> 8) & 255, a: num & 255 }
}

function mix(a: RGBA, b: RGBA, t: number): RGBA {
  return {
    r: Math.round(a.r + (b.r - a.r) * t),
    g: Math.round(a.g + (b.g - a.g) * t),
    b: Math.round(a.b + (b.b - a.b) * t),
    a: 255,
  }
}

function toHex(color: RGBA): string {
  const clamp = (value: number) => Math.max(0, Math.min(255, Math.round(value))).toString(16).padStart(2, "0")
  return `#${clamp(color.r)}${clamp(color.g)}${clamp(color.b)}`
}

/** Vertical gradient from brand color toward background (mockup style: dark base, bright crest). */
function gradientStops(brand: RGBA, background: RGBA, rows: number): RGBA[] {
  const stops: RGBA[] = []
  for (let i = 0; i < rows; i++) {
    const t = rows <= 1 ? 1 : i / (rows - 1)
    // bright at the crest (top), fading into the background at the tail
    const lift = 0.35 + 0.65 * (1 - t)
    stops.push(mix(background, brand, Math.min(1, lift)))
  }
  return stops
}

// ---------------------------------------------------------------------------
// Current-model resolution (mirrors tui context/local.tsx fallbackModel)
// ---------------------------------------------------------------------------

type ModelRefLite = { providerID: string; modelID: string }

function parseModel(value: string): ModelRefLite | undefined {
  const index = value.indexOf("/")
  if (index === -1) return { providerID: value, modelID: "" }
  return { providerID: value.slice(0, index), modelID: value.slice(index + 1) }
}

type StatePaths = { readonly path: { readonly state: string } }
type ModelJson = { recent?: Array<{ providerID: string; modelID: string }> }
type FsLike = { existsSync(path: string): boolean; readFileSync(path: string, encoding: "utf8"): string }
type PathLike = { join(...parts: string[]): string }

function readModelJson(state: StatePaths): ModelRefLite | undefined {
  try {
    // Plugins run under Bun: sync require is available at runtime.
    const fs = require("node:fs") as FsLike
    const path = require("node:path") as PathLike
    const file = path.join(state.path.state, "model.json")
    if (!fs.existsSync(file)) return undefined
    const raw = JSON.parse(fs.readFileSync(file, "utf8")) as ModelJson
    const first = raw.recent?.[0]
    return first ? { providerID: first.providerID, modelID: first.modelID } : undefined
  } catch {
    return undefined
  }
}

function isModelValid(providers: ReadonlyArray<{ id: string; models: Record<string, unknown> }>, ref: ModelRefLite | undefined): boolean {
  if (!ref || !ref.modelID) return false
  return providers.some((provider) => provider.id === ref.providerID && provider.models[ref.modelID] !== undefined)
}

function resolveCurrentModel(api: TuiPluginApi, modelTick: () => number, onModelFileChange: () => void): () => ModelRefLite | undefined {
  // Re-read model.json when the model picker or prompt cycle writes it, so the
  // banner swaps live on ctrl+x m switches.
  try {
    const fs = require("node:fs") as FsLike & { watchFile(path: string, listener: () => void): void; unwatchFile(path: string, listener?: () => void): void }
    const path = require("node:path") as PathLike
    const file = path.join(api.state.path.state, "model.json")
    const listener = () => onModelFileChange()
    fs.watchFile(file, { interval: 500 }, listener)
    api.lifecycle.onDispose(() => {
      fs.unwatchFile(file, listener)
    })
  } catch {
    // watch unavailable — banner stays static for this session
  }

  return createMemo(() => {
    modelTick() // dependency: re-resolve when model.json changes
    const providers = api.state.provider
    // 1. config `model` (opencode.json)
    const configModel = api.state.config.model
    if (typeof configModel === "string") {
      const ref = parseModel(configModel)
      if (isModelValid(providers, ref)) return ref
    }
    // 2. last used (state/model.json recent[0]) — matches core fallback chain
    const recent = readModelJson(api.state)
    if (isModelValid(providers, recent)) return recent
    // 3. first provider's default / first model
    const provider = providers[0]
    if (!provider) return undefined
    const firstModel = Object.values(provider.models)[0] as { id?: string } | undefined
    const modelID = firstModel?.id ?? Object.keys(provider.models)[0]
    if (!modelID) return undefined
    return { providerID: provider.id, modelID }
  })
}

function displayName(api: TuiPluginApi, ref: ModelRefLite | undefined): string {
  if (!ref) return ""
  const provider = api.state.provider.find((item) => item.id === ref.providerID)
  const info = provider?.models[ref.modelID] as { name?: string } | undefined
  return info?.name ?? ref.modelID
}

// ---------------------------------------------------------------------------
// Banner components
// ---------------------------------------------------------------------------

function HomeBanner(props: { api: TuiPluginApi; theme: TuiSlotContext["theme"]; ref: () => ModelRefLite | undefined }) {
  const brand = createMemo(() => {
    const ref = props.ref()
    if (!ref) return undefined
    const name = displayName(props.api, ref)
    const matched = matchArt(ref.providerID, ref.modelID, name)
    return { matched, ref, name }
  })

  // Derived entirely from the memo, so a model switch re-renders everything.
  const view = createMemo(() => {
    const value = brand()
    if (!value) return undefined
    const { matched, ref } = value
    const name = matched.name
    const theme = props.theme.current
    const bg = { r: theme.background.r * 255, g: theme.background.g * 255, b: theme.background.b * 255, a: 255 }
    const brandHex = matched.entry.color ?? "#8888AA"
    const brandColor = hexToRgba(brandHex)
    const allLines = matched.entry.lines
    // Generated smooth art: runs+colors. Legacy entries: plain lines.
    const runs: Array<Array<[number, string]>> | undefined = matched.entry.runs
    const palette = matched.entry.colors
    // Cap art height to ~40% of the terminal so the prompt stays visible.
    const maxRows = Math.max(4, Math.floor(props.api.renderer.height * 0.4))
    const keep = (n: number) => {
      if (n <= maxRows) return Array.from({ length: n }, (_, i) => i)
      const step = Math.ceil(n / maxRows)
      return Array.from({ length: n }, (_, i) => i)
        .filter(i => i === 0 || i === n - 1 || i % step !== 0)
    }
    const rowIdx = keep(runs ? runs.length : allLines.length)
    const stops = gradientStops(brandColor ?? { r: 120, g: 120, b: 160, a: 255 }, bg, rowIdx.length)
    return { name, ref, bg, brandColor, brandHex, runs, palette, allLines, rowIdx, stops, maxRows }
  })

  return (
    <Show when={view()}>
      <box flexDirection="column" alignItems="center" flexShrink={1} minHeight={0}>
        <box flexDirection="column" alignItems="center">
          <Index each={view()!.rowIdx}>
            {(row, i) => (
              <box flexDirection="row" flexShrink={0} minHeight={0}>
                {view()!.runs
                  ? (view()!.runs![i] ?? []).map(([ci, text], j) => (
                      <text fg={view()!.palette?.[ci] ?? view()!.brandHex}>{text}</text>
                    ))
                  : <text fg={toHex(view()!.stops[Math.min(i, view()!.stops.length - 1)]!)}>{view()!.allLines[i]}</text>
                }
              </box>
            )}
          </Index>
        </box>
        <box flexDirection="row" gap={1} paddingTop={0}>
          <text fg={toHex(view()!.brandColor ?? { r: 150, g: 150, b: 180, a: 255 })}>{view()!.name}</text>
          <Show when={view()!.ref?.providerID}>
            <text fg={toHex(mix(view()!.bg, view()!.brandColor ?? { r: 120, g: 120, b: 160, a: 255 }, 0.45))}>
              ({view()!.ref?.providerID})
            </text>
          </Show>
        </box>
      </box>
    </Show>
  )
}

// One-line signature glyphs for the compact session banner.
const SESSION_GLYPHS: Record<string, string> = {
  deepseek: "–<}}}}<",
  "z-ai": "◈",
  zai: "◈",
  moonshotai: "☾",
  moonshot: "☾",
  "x-ai": "✦",
  xai: "✦",
  grok: "✦",
  qwen: "∮",
  minimax: "☰",
  openai: "❖",
  anthropic: "❍",
  google: "✧",
  mistralai: "▮▮",
  mistral: "▮▮",
  nvidia: "▲",
  xiaomi: "◉",
  stepfun: "⇉",
  sakana: "≈",
  tencent: "⌬",
  miromind: "❂",
  bytedance: "❖",
  opencode: "⬢",
}

function sessionGlyph(providerID: string, modelID: string): string {
  const key = providerID.toLowerCase()
  if (SESSION_GLYPHS[key]) return SESSION_GLYPHS[key]!
  const brand = Object.keys(SESSION_GLYPHS).find((name) => key.includes(name) || modelID.toLowerCase().includes(name))
  return brand ? SESSION_GLYPHS[brand]! : "◈"
}

// ---------------------------------------------------------------------------
// Running-state indicator (session banner animates while the model runs)
// ---------------------------------------------------------------------------

// Mirrors the SDK SessionStatus shape without importing the SDK package.
type RunStatus = { type: "idle" } | { type: "busy" } | { type: "retry"; attempt: number; message: string; next: number }

// Triangle wave of block heights; the frame offset scrolls it left→right.
const WAVE = "▁▂▃▄▅▆▇█▇▆▅▄▃▂"
const WAVE_FRAMES = WAVE.length
const WAVE_COLS = 10
const FRAME_MS = 100

function SessionBanner(props: { api: TuiPluginApi; ref: () => ModelRefLite | undefined; sessionID: string; status: () => RunStatus | undefined }) {
  const brand = createMemo(() => {
    const ref = props.ref()
    if (!ref) return undefined
    // Use the current model (matches the prompt footer, swaps live on switch).
    const raw = displayName(props.api, ref)
    const matched = matchArt(ref.providerID, ref.modelID, raw)
    return { matched, active: ref, name: matched.name }
  })

  // Derived in a memo so model switches re-render (no cached function child).
  const view = createMemo(() => {
    const value = brand()
    if (!value) return undefined
    const { matched, active, name } = value
    const brandColor = hexToRgba(matched.entry.color ?? "#8888AA") ?? { r: 130, g: 130, b: 160, a: 255 }
    const glyph = sessionGlyph(active.providerID, active.modelID)
    const bg = (() => {
      const t = props.api.theme.current
      return { r: t.background.r * 255, g: t.background.g * 255, b: t.background.b * 255, a: 255 }
    })()
    return { glyph, name, colorHex: toHex(brandColor), brandColor, bg }
  })

  // Animate only while the session is busy (idle renders read no frame signal).
  const [frame, setFrame] = createSignal(0)
  createEffect(() => {
    const st = props.status()
    if (!st || st.type === "idle") return
    const timer = setInterval(() => setFrame((f) => (f + 1) % WAVE_FRAMES), FRAME_MS)
    onCleanup(() => clearInterval(timer))
  })

  const running = createMemo(() => {
    const st = props.status()
    return st && st.type !== "idle" ? st : undefined
  })
  const statusText = createMemo(() => {
    const st = running()
    if (!st) return undefined
    if (st.type === "retry") return `retrying · attempt ${st.attempt}…`
    return "thinking…"
  })

  return (
    <Show when={view()}>
      <box flexDirection="row" gap={1} justifyContent="center" flexShrink={0} paddingBottom={0}>
        <Show
          when={running()}
          fallback={
            <>
              <text fg={view()!.colorHex}>{view()!.glyph}</text>
              <text fg={view()!.colorHex}>{view()!.name}</text>
            </>
          }
        >
          <text fg={view()!.colorHex}>{view()!.glyph}</text>
          <box flexDirection="row" flexShrink={0}>
            <Index each={Array.from({ length: WAVE_COLS })}>
              {(_, i) => <text fg={view()!.colorHex}>{WAVE[(frame() + i * 2) % WAVE_FRAMES]}</text>}
            </Index>
          </box>
          <text fg={view()!.colorHex}>{view()!.name}</text>
          <Show when={statusText()}>
            <text fg={toHex(mix(view()!.bg, view()!.brandColor, 0.55))}>{statusText()}</text>
          </Show>
        </Show>
      </box>
    </Show>
  )
}

// ---------------------------------------------------------------------------
// Plugin
// ---------------------------------------------------------------------------

const tui: TuiPlugin = async (api) => {
  const [modelFileTick, setModelFileTick] = createSignal(0)
  const ref = resolveCurrentModel(api, modelFileTick, () => setModelFileTick((n) => n + 1))

  // Track the active session's run state so the session banner can animate
  // while the model streams (session.status: idle | busy | retry).
  const [statusBySession, setStatusBySession] = createSignal<Record<string, RunStatus>>({})
  const statusOf = (sessionID: string) => statusBySession()[sessionID]
  api.event.on("session.status", (event) => {
    const { sessionID, status } = event.properties
    setStatusBySession((prev) => ({ ...prev, [sessionID]: status as RunStatus }))
  })

  const bannerFor = (sessionID: string) => (
    <SessionBanner api={api} ref={ref} sessionID={sessionID} status={() => statusOf(sessionID)} />
  )

  api.slots.register({
    order: 0,
    slots: {
      home_logo(ctx: TuiSlotContext) {
        return <HomeBanner api={api} theme={ctx.theme} ref={ref} />
      },
    },
  })

  api.slots.register({
    order: 0,
    slots: {
      session_prompt(ctx, value) {
        const Prompt = api.ui.Prompt
        const Slot = api.ui.Slot
        return (
          <box flexDirection="column" flexShrink={0}>
            {bannerFor(value.session_id)}
            <Prompt
              sessionID={value.session_id}
              visible={value.visible}
              disabled={value.disabled}
              onSubmit={value.on_submit}
              ref={value.ref}
              right={<Slot name="session_prompt_right" session_id={value.session_id} />}
            />
          </box>
        )
      },
    },
  })
}

export default {
  id: "model-banner",
  tui,
}
